    source=record.source;dialoguePlayer=new SceneDialoguePlayback(source,frame);onDirty();frame=Math.min(frame,source.frameCount-1);pause();options();renderTracks();renderInspector();void rebuildPreview().catch(e=>report(String(e),true));
    const json=body.querySelector<HTMLTextAreaElement>('[data-json]');if(json)json.value=JSON.stringify(source,null,2);
