      const catalog=nativeSkeletalCatalog(doc);rigs=nativeSceneGroups(doc).flatMap((ids,model)=>{const binding=catalog.find(b=>ids.includes(b.modelId)&&ids.includes(b.animationId));return binding?[{...binding,model}]:[];});
      const track=src.skeletal?.find(t=>t.keys.some(k=>k.id===selected));if(track){const binding=rigs.find(b=>b.modelId===track.modelId&&b.animationId===track.animationId);if(binding)activeJoint={model:binding.model,node:track.jointIndex};}
