    const position=(f:number)=>Math.max(0,Math.min(src.frameCount-1,f))/denominator*100;
    const marker=(k:SceneKeyframe|SceneEvent|SceneNpcKey|SceneJointKey,kind:string)=>`<button class="scene-marker ${kind==='camera'?'camera-key':''} ${selected===k.id?'selected':''}" data-item="${esc(k.id)}" style="left:${position(k.frame)}%;${'durationFrames'in k&&!('waitForInput'in k&&k.waitForInput)?`width:max(15px,${k.durationFrames/denominator*100}%);`:''}" aria-label="${esc(kind==='camera'?`Camera ${k.id}, frame ${k.frame}`:kind==='joint'?`Joint ${k.id}, frame ${k.frame}`:kind==='actor'?`NPC ${k.id}, frame ${k.frame}`:`${eventNames[(k as SceneEvent).type]} ${k.id}, frame ${k.frame}`)}" title="${esc(k.id)} · ${k.frame<0?'Preload':k.frame>=src.frameCount?`After camera range · frame ${k.frame}`:`Frame ${k.frame}`}" type="button">${kind==='camera'?'◆':kind==='joint'?'◆':kind==='actor'?'●':esc(eventNames[(k as SceneEvent).type])}</button>`;
    const ticks=Array.from({length:11},(_,i)=>`<span style="left:${i*10}%">${Math.round(i*(src.frameCount-1)/10)}</span>`).join('');
