    const branches=body.querySelector<HTMLElement>('[data-branches]');if(branches)branches.innerHTML=src.events.flatMap(e=>e.type==='dialogue.choice'?e.choices.map(c=>`<button data-action="branch-target" data-target-frame="${c.targetFrame}" title="${esc(e.id)}">${esc(c.text)} → frame ${c.targetFrame}</button>`):e.type==='timeline.jump'?[`<button data-action="branch-target" data-target-frame="${e.targetFrame}">${esc(e.id)} → frame ${e.targetFrame}</button>`]:[]).join('');
    b('[data-action="undo"]').disabled=!undo.length;b('[data-action="redo"]').disabled=!redo.length;
    const name=body.querySelector<HTMLInputElement>('[name="scene-name"]');if(name)name.value=src.name;
    const length=body.querySelector<HTMLInputElement>('[name="duration"]');if(length)length.value=String(src.frameCount);
